package com.subhamviky.settlement.service;

import com.subhamviky.settlement.common.E2ABase.BaseAgent;

import java.math.BigDecimal;
import java.util.*;

/**
 * SettlementPolicyAgent — generated by G2C (e2a_inherited); hooks implemented by hand.
 *
 * A deterministic policy gate built on the E2A agent lifecycle: no model is
 * called. run() (inherited, final) calls buildMessages() and applyPolicy(); any
 * exception goes to handleError(), which REJECTS. The caller treats every
 * decision other than APPROVED as a rejection, so the gate fails closed.
 */
public class SettlementPolicyAgent extends BaseAgent {
    public static final String AGENT_NAME = "SettlementPolicyAgent";

    @Override
    protected Object buildMessages(Map<String, Object> state, Map<String, Object> config) {
        String summary = "settle " + state.get("amount") + " " + state.get("currency")
                + " from " + state.get("payer_account") + " to " + state.get("payee_account")
                + " for tenant " + state.get("tenant_id");
        state.put("policy_input", summary);
        return List.of(Map.of("role", "system", "content", "You are " + AGENT_NAME + "."),
                Map.of("role", "user", "content", summary));
    }

    @Override
    @SuppressWarnings("unchecked")
    protected Object applyPolicy(Map<String, Object> state, Map<String, Object> config) {
        BigDecimal amount = new BigDecimal(String.valueOf(state.get("amount")));
        BigDecimal maxAmount = new BigDecimal(String.valueOf(config.getOrDefault("max_amount", "1000000.00")));
        Set<String> blocked = (Set<String>) config.getOrDefault("blocked_accounts", Set.of());
        String payer = String.valueOf(state.get("payer_account"));
        String payee = String.valueOf(state.get("payee_account"));

        List<String> violations = new ArrayList<>();
        if (payer.equals(payee)) {
            violations.add("payer and payee must be different accounts");
        }
        if (amount.compareTo(maxAmount) > 0) {
            violations.add("amount " + amount.toPlainString() + " exceeds the policy limit " + maxAmount.toPlainString());
        }
        if (blocked.contains(payer) || blocked.contains(payee)) {
            violations.add("a blocked account is involved");
        }
        state.put("violations", violations);
        state.put("decision", violations.isEmpty() ? "APPROVED" : "REJECTED");
        return state;
    }

    @Override
    protected Object evaluateOutput(Map<String, Object> state, Map<String, Object> config) {
        return "APPROVED".equals(state.get("decision")) ? 1.0 : 0.0;
    }

    @Override
    protected Object fallback(Map<String, Object> state, Map<String, Object> config) {
        state.put("decision", "REJECTED");
        return state;
    }

    @Override
    protected Object handleError(Map<String, Object> state, Map<String, Object> config) {
        state.put("decision", "REJECTED");
        state.put("violations", List.of("policy evaluation failed: " + state.get("error")));
        return state;
    }
}
